test('issueInvoice: multiple invoices same day', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.ok(r1.ok);
  assert.ok(r2.ok);

  const issue1 = issueInvoice(r1.value, []);
  assert.ok(issue1.ok);
  assert.equal(issue1.value.number, 'INV-2026-0001');

  const issue2 = issueInvoice(r2.value, [issue1.value.number]);
  assert.ok(issue2.ok);
  assert.equal(issue2.value.number, 'INV-2026-0002');
});

