import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText: draft invoice with one line', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Blue Fern Bakery'));
  assert.ok(text.includes('8 ×'));
  assert.ok(text.includes('Development (hour)'));
  assert.ok(text.includes('€95.00'));
  assert.ok(text.includes('€760.00'));
  assert.ok(text.includes('Total: €760.00'));
});

test('renderInvoiceText: draft invoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Blue Fern Bakery'));
  assert.ok(text.includes('8 × Development (hour)'));
  assert.ok(text.includes('5 × Design work (hour)'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText: issued invoice with number', () => {
  // C-002 is standard tier (no automatic discount)
  const createResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(createResult.ok);

  const issueResult = issueInvoice(createResult.value, []);
  assert.ok(issueResult.ok);

  const text = renderInvoiceText(issueResult.value);

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(!text.includes('DRAFT'));
  assert.ok(text.includes('Blue Fern Bakery'));
});

test('renderInvoiceText: formats amounts as euros', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  // Logo package costs 120000 cents = €1,200.00
  // VAT: 120000 * 21 / 100 = 25200
  // Total: 120000 + 25200 = 145200 = €1,452.00
  assert.ok(text.includes('€1,200.00'));
  assert.ok(text.includes('Subtotal: €1,200.00'));
  assert.ok(text.includes('VAT: +€252.00'));
  assert.ok(text.includes('Total: €1,452.00'));
});

test('renderInvoiceText: small amounts formatted correctly', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  // Sticker costs 50 cents = €0.50 per unit, 5 = €2.50 total
  // VAT: 250 * 21 / 100 = 52.5 -> rounds to 52 (banker's rounding)
  // Total: 250 + 52 = 302 = €3.02
  assert.ok(text.includes('€0.50'));
  assert.ok(text.includes('Subtotal: €2.50'));
  assert.ok(text.includes('VAT: +€0.52'));
  assert.ok(text.includes('Total: €3.02'));
});

test('renderInvoiceText: line format', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.ok(lines[2].includes('8 ×'));
  assert.ok(lines[2].includes('Development (hour)'));
  assert.ok(lines[2].includes('@'));
  assert.ok(lines[2].includes('='));
  // With VAT: DRAFT, customer, line, Subtotal, VAT, Total
  assert.ok(lines[3].includes('Subtotal:'));
  assert.ok(lines[4].includes('VAT:'));
  assert.ok(lines[5].includes('Total:'));
});

test('renderInvoiceText: multiple lines format', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  // Now with VAT: DRAFT, customer, 3 lines, Subtotal, VAT, Total = 8 lines
  assert.equal(lines.length, 8);
  assert.ok(lines[2].includes('Development (hour)'));
  assert.ok(lines[3].includes('Design work (hour)'));
  assert.ok(lines[4].includes('Copywriting (hour)'));
  assert.ok(lines[5].includes('Subtotal:'));
  assert.ok(lines[6].includes('VAT:'));
  assert.ok(lines[7].includes('Total:'));
});

test('renderInvoiceText: total calculation', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  // Dev: 95000, VAT 21% = 19950
  // Des: 42500, VAT 21% = 8925
  // Subtotal: 137500, VAT: 28875, Total: 166375
  assert.ok(text.includes('Subtotal: €1,375.00'));
  assert.ok(text.includes('VAT: +€288.75'));
  assert.ok(text.includes('Total: €1,663.75'));
});

test('renderInvoiceText: different customers', () => {
  const c1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const c2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.ok(c1.ok);
  assert.ok(c2.ok);

  const text1 = renderInvoiceText(c1.value);
  const text2 = renderInvoiceText(c2.value);

  assert.ok(text1.includes('Northwind Studio'));
  assert.ok(text2.includes('Kite & Co'));
  assert.notEqual(text1, text2);
});

test('renderInvoiceText: issued invoice from workflow', () => {
  const createResult = createInvoice({
    customerId: 'C-005',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'SUPPORT-HOUR', qty: 20 },
      { sku: 'HOST-MONTH', qty: 3 },
    ],
  });

  assert.ok(createResult.ok);

  const issueResult = issueInvoice(createResult.value, ['INV-2026-0001']);
  assert.ok(issueResult.ok);

  const text = renderInvoiceText(issueResult.value);

  assert.ok(text.includes('INV-2026-0002'));
  assert.ok(text.includes('Orchard Health'));
  assert.ok(text.includes('20 × Support (hour)'));
  assert.ok(text.includes('3 × Website hosting (month)'));
  assert.ok(text.includes('€72.50'));
  assert.ok(text.includes('€15.00'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText: draft invoice with discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 10 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Northwind Studio'));
  assert.ok(text.includes('10% off'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  // Line total: 76000, discount 10% = 7600, discounted = 68400, VAT 21% = 14364, total = 82764
  assert.ok(text.includes('€760.00'));
  assert.ok(text.includes('-€76.00'));
  assert.ok(text.includes('VAT: +€143.64'));
  assert.ok(text.includes('Total: €827.64'));
});

test('renderInvoiceText: invoice with multiple lines and different discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('8 × Development (hour)'));
  assert.ok(text.includes('10% off'));
  assert.ok(text.includes('5 × Design work (hour)'));
  assert.ok(text.includes('20% off'));
  // Dev: 76000, discount 10% = 7600, discounted = 68400, VAT 21% = 14364
  // Des: 42500, discount 20% = 8500, discounted = 34000, VAT 21% = 7140
  // Subtotal: 118500, Discount: 16100, VAT: 21504, Total: 123904
  assert.ok(text.includes('Subtotal: €1,185.00'));
  assert.ok(text.includes('Discount: -€161.00'));
  assert.ok(text.includes('VAT: +€215.04'));
  assert.ok(text.includes('Total: €1,239.04'));
});

