test('renderInvoiceText: mixed discount and no-discount lines', () => {
  // C-002 is standard tier (no automatic discount), so we can mix 10% explicit and no discount
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('10% off'));
  assert.ok(text.includes('Development (hour)'));
  assert.ok(text.includes('Design work (hour)'));
  const lines = text.split('\n');
  const designLine = lines.find((l) => l.includes('Design work'));
  assert.ok(!designLine.includes('off'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
});

test('renderInvoiceText: decimal discount percent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 12.5 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('12.5% off'));
  // 8 * 9500 = 76000, discount 12.5% = 9500, discounted = 66500, VAT 21% = 13965, total = 80465
  assert.ok(text.includes('-€95.00'));
  assert.ok(text.includes('Discount: -€95.00'));
  assert.ok(text.includes('VAT: +€139.65'));
  assert.ok(text.includes('Total: €804.65'));
});

